               AND cr_state.request_id = (NULLIF(current_setting('registry.change_request_action_context', true), '')::jsonb ->> 'requestId')::uuid
               AND cr_state.proposal_version = (NULLIF(current_setting('registry.change_request_action_context', true), '')::jsonb ->> 'proposalVersion')::bigint
               AND cr_state.state IN ('approved')
        ) AND record_lifecycle = 'active');
CREATE VIEW registry_source."person"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "rs_f_person_person_code_7514464caf72c5a7" AS "person_code", "rs_f_person_display_name_d9351abe753f7258" AS "display_name"
                    FROM registry_data."rs_e_person_a28225974420754a"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_source."person_name_change_request"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "rs_f_person_name_change_request_person_f412f4d59488b518" AS "person", "rs_f_person_name_change_request_given_name_342662a0f9a0953e" AS "given_name", "rs_f_person_name_change_request_family_name_b9c8a78be7cd45ab" AS "family_name", "rs_f_person_name_change_request_handling_f905874ecf9c8f1f" AS "handling"
                    FROM registry_data."rs_e_person_name_change_request_11cbf1df2431a652"
                   WHERE record_lifecycle = 'active';
